from fastapi.responses import HTMLResponse


def arkime_page() -> HTMLResponse:
    return HTMLResponse(r'''<!doctype html>
<html class="nct-shell-loading" lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NCT · Arkime Sessions JSON</title><style id="nct-shell-bootstrap">html.nct-shell-loading body{visibility:hidden}</style>
<style>:root{color-scheme:dark;--bg:#09131c;--panel:#112330;--line:#304955;--text:#e8f2f6;--muted:#abc0cb;--accent:#62d9ba;--warn:#f4c66b;--bad:#ff9b9b}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui}header{padding:20px 4vw;border-bottom:1px solid var(--line)}main{max-width:1500px;margin:auto;padding:30px 24px}.panel{margin:0 0 18px;padding:22px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}h1{margin:0;font-size:30px}h2{margin:0 0 10px;font-size:20px}p,.muted,small{color:var(--muted)}.notice{padding:12px 14px;border-left:4px solid var(--warn);background:#f4c66b12;color:var(--text)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}label{display:grid;gap:5px;font-weight:700}input,select,textarea,button{font:inherit;border:1px solid var(--line);border-radius:7px;background:#0b1b26;color:var(--text);padding:9px 11px}textarea{min-height:75px;resize:vertical}button{cursor:pointer;font-weight:750;background:#193445}button.primary{background:var(--accent);color:#09251d}button:disabled{opacity:.5;cursor:not-allowed}.actions{display:flex;flex-wrap:wrap;gap:9px;align-items:center}.table-wrap{overflow:auto;max-width:100%;border:1px solid var(--line);border-radius:9px}table{width:100%;min-width:1120px;border-collapse:collapse}th,td{padding:11px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{background:#172d3a;color:var(--text);font-size:12px}td>strong,td>small{display:block}td>small{margin-top:4px}.badge{display:inline-block;padding:2px 8px;border:1px solid var(--line);border-radius:999px;font-size:12px}.badge.complete{border-color:#35bc91;color:#7ff0ca}.badge.partial,.badge.unknown{border-color:#a9883b;color:#f4d37e}.bad{color:var(--bad)}.status{min-height:24px}.progress{width:100%;height:8px;margin:8px 0 14px;border:0;border-radius:999px;overflow:hidden;background:#08131c}.progress::-webkit-progress-bar{background:#08131c}.progress::-webkit-progress-value{background:var(--accent)}.progress:indeterminate{animation:pulse 1.4s ease-in-out infinite}@keyframes pulse{50%{opacity:.45}}.pager{justify-content:space-between;margin-top:12px}.session-table{margin-top:10px}.session-table table{min-width:980px}.source-note{margin:8px 0 0}.nowrap{white-space:nowrap}@media(max-width:1100px){.grid{grid-template-columns:1fr}}@media(max-width:760px){main{padding:20px 12px}}</style>
<script src="/assets/nct-session.js"></script></head><body><header><strong>NCT</strong> · Network Correlation &amp; Triage</header><main>
<div class="notice" data-guide-context="arkime-boundary"><strong>Manual Sessions JSON only.</strong> This page does not contact Arkime or ingest packet captures. A session is passively observed traffic; it does not prove that a destination port is currently open. NCT keeps overlapping uploads separate and does not add their counts together.</div>
<section class="panel" id="arkimeUpload" data-guide-context="arkime-upload"><h2>Import Sessions JSON</h2>
<p>In Arkime, export the selected Sessions query as JSON. Record the same query window and bounding mode here. Query-result completeness and capture coverage are separate because a complete export can still come from a sensor with gaps.</p>
<form id="uploadForm"><div class="grid">
<label>Sessions JSON file<input id="file" name="file" type="file" accept="application/json,.json" required></label>
<label>Network Scope<select id="scope" name="scope_id" required><option value="">Loading active scopes…</option></select></label>
<label>Operator sensor label<input id="sensor" name="operator_sensor" maxlength="200" placeholder="Example: range-arkime-vyos-trunk" required></label>
<label>Arkime query bounding<select id="bounding" name="bounding_mode"><option value="both">Both packet times inside window</option><option value="either">Session overlaps window</option><option value="first">First packet inside window</option><option value="last">Last packet inside window</option></select></label>
<label>Query start<input id="queryStart" type="datetime-local" step="1" required></label>
<label>Query end<input id="queryEnd" type="datetime-local" step="1" required></label>
<label>Operator export assessment<select id="operatorAssessment" name="operator_export_assessment"><option value="unknown">Unknown</option><option value="complete">Complete query export</option><option value="partial">Partial query export</option></select></label>
<label>Capture coverage<select id="captureCoverage" name="capture_coverage"><option value="unknown">Unknown</option><option value="partial">Partial or known gaps</option><option value="complete">Complete for this declared window</option></select></label>
</div><label>Arkime query expression (optional)<textarea id="expression" name="query_expression" maxlength="2000" placeholder="Example: vlan == 10"></textarea></label>
<p class="source-note">Limits: 10 MiB and 10,000 returned sessions. Unsupported OpenSearch exports and database-time searches are rejected. Original bytes are retained by exact SHA-256 identity.</p>
<div class="actions"><button class="primary" id="upload" type="submit">Retain and inspect export</button></div></form>
<progress id="progress" class="progress" hidden></progress><p id="uploadStatus" class="status" role="status" aria-live="polite"></p></section>
<section class="panel" id="arkimeHistory" data-guide-context="arkime-history"><h2>Retained Arkime imports</h2><p>Each row is one source encounter. Matching bytes share canonical storage, but each upload keeps its own operator, time, scope, and sensor record.</p>
<div class="actions"><label>Network Scope<select id="filterScope"><option value="">All active and historical scopes</option></select></label><button id="refresh" type="button">Refresh retained imports</button></div>
<progress id="historyProgress" class="progress" hidden></progress><p id="historyStatus" class="status" role="status" aria-live="polite"></p>
<div class="table-wrap" data-nct-table-mode="contained" data-nct-guide-mode="contained" data-nct-narrow-mode="contained" tabindex="0" role="region" aria-label="Retained Arkime imports"><table><thead><tr><th>Imported</th><th>Network Scope</th><th>Sensor and query</th><th>Export status</th><th>Sessions</th><th>Source</th></tr></thead><tbody id="rows"><tr><td colspan="6">Loading retained imports…</td></tr></tbody></table></div>
<div class="actions pager"><span id="page" class="muted"></span><span class="actions"><button id="previous" type="button">Previous</button><button id="next" type="button">Next</button></span></div></section>
</main><script>(()=>{
const $=id=>document.getElementById(id),limit=25;let offset=0,total=0,revision='',historyRequest=0;
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function localInput(date){const pad=value=>String(value).padStart(2,'0');return`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`}
const end=new Date(),start=new Date(end.getTime()-24*60*60*1000);$('queryStart').value=localInput(start);$('queryEnd').value=localInput(end);
function badge(value){return`<span class="badge ${esc(value)}">${esc(value)}</span>`}
async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options});let data={};try{data=await response.json()}catch(_){}if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Request failed');return data}
function busy(id,on){$(id).hidden=!on}
async function loadScopes(){try{const items=await api('/api/nmap-assignment-scopes');for(const select of[$('scope'),$('filterScope')]){const first=select=== $('scope')?new Option('Choose an active Network Scope',''):new Option('All active and historical scopes','');select.replaceChildren(first,...items.map(item=>new Option(item.label,item.scope_id)))}}catch(error){$('scope').replaceChildren(new Option('Active scopes unavailable',''));$('uploadStatus').textContent=error.message;$('uploadStatus').className='status bad'}}
function sessionTable(data,host,importId){const wrap=document.createElement('div');wrap.className='table-wrap session-table';wrap.dataset.nctTableMode='contained';const table=document.createElement('table');table.innerHTML='<thead><tr><th>Source row</th><th>First / last packet</th><th>Source</th><th>Destination</th><th>Transport / application</th><th>Packets / bytes</th><th>Source node / VLAN</th></tr></thead><tbody></tbody>';const body=table.tBodies[0];for(const item of data.sessions){const tr=document.createElement('tr');const source=`${esc(item.source_ip)}${item.source_port===null?'':`:${item.source_port}`}`,destination=`${esc(item.destination_ip)}${item.destination_port===null?'':`:${item.destination_port}`}`;tr.innerHTML=`<td>${item.source_ordinal+1}<small>${esc(item.session_id||'No session ID')}</small></td><td class="nowrap">${esc(new Date(item.first_packet).toLocaleString())}<small>${esc(new Date(item.last_packet).toLocaleString())}</small></td><td>${source}</td><td>${destination}</td><td>${esc(item.transport||'Unknown')}<small>${esc(item.applications.join(', ')||'Application unknown')}</small></td><td>${item.packet_count??'Unknown'}<small>${item.byte_count??'Unknown'} bytes</small></td><td>${esc(item.source_node||'Source node not present')}<small>${esc(item.vlans.length?item.vlans.join(', '):'No VLAN field')}</small></td>`;body.append(tr)}if(!data.sessions.length){const tr=document.createElement('tr');tr.innerHTML='<td colspan="7">This retained export contains no session rows.</td>';body.append(tr)}wrap.append(table);host.replaceChildren(wrap);const page=document.createElement('div'),summary=document.createElement('span'),controls=document.createElement('span'),previous=document.createElement('button'),next=document.createElement('button');page.className='actions pager';controls.className='actions';previous.type=next.type='button';previous.textContent='Previous 100 sessions';next.textContent='Next 100 sessions';const start=data.pagination.total?data.pagination.offset+1:0,end=Math.min(data.pagination.offset+data.sessions.length,data.pagination.total);summary.className='muted';summary.textContent=`Sessions ${start}–${end} of ${data.pagination.total}`;previous.disabled=data.pagination.offset===0;next.disabled=!data.pagination.has_more;previous.onclick=()=>loadSessionPage(importId,host,Math.max(0,data.pagination.offset-100));next.onclick=()=>loadSessionPage(importId,host,data.pagination.offset+100);controls.append(previous,next);page.append(summary,controls);host.append(page)}
async function loadSessionPage(importId,host,target){host.className='';host.textContent='Loading retained session receipts…';try{const data=await api(`/api/arkime/imports/${encodeURIComponent(importId)}?limit=100&offset=${Math.max(0,target)}`);sessionTable(data,host,importId)}catch(error){host.textContent=error.message;host.className='bad'}}
async function expand(button,importId,host){button.disabled=true;button.textContent='Session receipts loaded';await loadSessionPage(importId,host,0)}
function render(data){const body=$('rows');body.replaceChildren();revision=data.source_revision;total=data.pagination.total;offset=data.pagination.offset;if(!data.items.length){const tr=document.createElement('tr');tr.innerHTML='<td colspan="6">No retained Arkime imports match this view.</td>';body.append(tr)}for(const item of data.items){const tr=document.createElement('tr'),detail=document.createElement('tr'),detailCell=document.createElement('td'),button=document.createElement('button');detailCell.colSpan=6;detailCell.hidden=true;detail.append(detailCell);button.type='button';button.textContent='Show session receipts';button.onclick=()=>{detailCell.hidden=false;expand(button,item.import_id,detailCell)};tr.innerHTML=`<td>${esc(new Date(item.imported_at).toLocaleString())}<small>${esc(item.actor)}</small></td><td><strong>${esc(item.scope.label)}</strong><small>Version ${item.scope.version}</small></td><td><strong>${esc(item.operator_sensor)}</strong><small>${esc(new Date(item.query_start).toLocaleString())} – ${esc(new Date(item.query_end).toLocaleString())}</small><small>${esc(item.bounding_mode)} bounding${item.query_expression?` · ${esc(item.query_expression)}`:''}</small></td><td>Calculated ${badge(item.calculated_export_completeness)}<small>Operator export: ${esc(item.operator_export_assessment)}</small><small>Capture coverage: ${esc(item.capture_coverage)}</small></td><td><strong>${item.returned_count}</strong><small>${item.records_filtered===null?'Matching total not present':`${item.records_filtered} matching in Arkime response`}</small></td><td><a href="${esc(item.raw_url)}">Download exact source</a><small>${esc(item.parser_version)}</small></td>`;tr.cells[4].append(document.createElement('br'),button);body.append(tr,detail)}$('previous').disabled=offset===0;$('next').disabled=!data.pagination.has_more;const first=total?offset+1:0,last=Math.min(offset+data.items.length,total);$('page').textContent=`${first}–${last} of ${total}`}
async function load(target=0,stable=false){const requestId=++historyRequest,requestedOffset=Math.max(0,target),selectedScope=$('filterScope').value;if(!stable)revision='';const requestedRevision=revision;busy('historyProgress',true);$('historyStatus').textContent='Loading retained Arkime imports…';$('historyStatus').className='status';$('previous').disabled=$('next').disabled=true;$('rows').innerHTML='<tr><td colspan="6">Loading retained imports…</td></tr>';try{const params=new URLSearchParams({limit:String(limit),offset:String(requestedOffset)});if(selectedScope)params.set('scope_id',selectedScope);if(requestedRevision)params.set('revision',requestedRevision);const data=await api(`/api/arkime/imports?${params}`);if(requestId!==historyRequest)return;render(data);$('historyStatus').textContent='Showing saved receipts only. Opening this page does not re-read the JSON source.';$('historyStatus').className='status'}catch(error){if(requestId!==historyRequest)return;if(stable&&requestedOffset){revision='';return load(0,false)}$('historyStatus').textContent=error.message;$('historyStatus').className='status bad'}finally{if(requestId===historyRequest)busy('historyProgress',false)}}
$('uploadForm').onsubmit=async event=>{event.preventDefault();const file=$('file').files[0];if(!file)return;const start=new Date($('queryStart').value),end=new Date($('queryEnd').value);if(Number.isNaN(start.valueOf())||Number.isNaN(end.valueOf())){$('uploadStatus').textContent='Enter a valid query start and end.';$('uploadStatus').className='status bad';return}const data=new FormData();data.append('file',file);data.append('scope_id',$('scope').value);data.append('operator_sensor',$('sensor').value);data.append('query_start',start.toISOString());data.append('query_end',end.toISOString());data.append('bounding_mode',$('bounding').value);data.append('operator_export_assessment',$('operatorAssessment').value);data.append('capture_coverage',$('captureCoverage').value);data.append('query_expression',$('expression').value);$('upload').disabled=true;busy('progress',true);$('uploadStatus').textContent='Validating the whole export before retaining it…';$('uploadStatus').className='status';try{const result=await api('/api/arkime/imports',{method:'POST',body:data});$('uploadStatus').textContent=`Retained ${result.returned_count} session receipts for ${result.scope.label}. Exact source SHA-256: ${result.sha256}.`;$('file').value='';await load(0,false)}catch(error){$('uploadStatus').textContent=error.message;$('uploadStatus').className='status bad'}finally{$('upload').disabled=false;busy('progress',false)}};
$('refresh').onclick=()=>load(0,false);$('filterScope').onchange=()=>load(0,false);$('previous').onclick=()=>load(Math.max(0,offset-limit),true);$('next').onclick=()=>load(offset+limit,true);loadScopes().then(()=>load(0,false));
})();</script></body></html>''')
